<?php
/**
 * Seed the disposable WordPress with cards covering every Phase 7 scenario.
 *
 * Run inside the e2e container after seed-reference.php:
 *   docker compose exec -T -u www-data wp php .../tests/e2e/seed-phase7.php
 *
 * Requires the gallery fixtures generated by
 * tests/e2e/fixtures/generate-images.php. Prints a JSON document with the
 * media and the URLs the host-side checks request.
 *
 * @package MyECardExtensions
 */

error_reporting( E_ALL & ~E_DEPRECATED & ~E_USER_DEPRECATED );

require '/var/www/html/wp-load.php';

require_once ABSPATH . 'wp-admin/includes/file.php';
require_once ABSPATH . 'wp-admin/includes/media.php';
require_once ABSPATH . 'wp-admin/includes/image.php';

$fixtures      = MY_ECARD_PATH . 'tests/e2e/fixtures/';
$stored        = get_option( 'my_ecard_e2e_phase7_media', array() );
$media         = array();
$gallery_keys  = array( 'gallery-1', 'gallery-2', 'gallery-3' );
$gallery_files = array(
	'gallery-1' => 'gallery-1.jpg',
	'gallery-2' => 'gallery-2.jpg',
	'gallery-3' => 'gallery-3.jpg',
);

foreach ( $gallery_files as $key => $file ) {
	$existing = isset( $stored[ $key ] ) ? (int) $stored[ $key ] : 0;

	if ( $existing > 0 && 'attachment' === get_post_type( $existing ) ) {
		$media[ $key ] = $existing;
		continue;
	}

	if ( ! is_readable( $fixtures . $file ) ) {
		fwrite( STDERR, 'missing fixture: ' . $file . "\n" );
		exit( 1 );
	}

	$temporary = wp_tempnam( $file );

	if ( ! $temporary || ! copy( $fixtures . $file, $temporary ) ) {
		fwrite( STDERR, 'unable to stage fixture: ' . $file . "\n" );
		exit( 1 );
	}

	$attachment_id = media_handle_sideload(
		array(
			'name'     => $file,
			'tmp_name' => $temporary,
		),
		0,
		'Phase 7 e2e ' . $key
	);

	if ( is_wp_error( $attachment_id ) ) {
		@unlink( $temporary );
		fwrite( STDERR, 'sideload failed: ' . $attachment_id->get_error_message() . "\n" );
		exit( 1 );
	}

	$media[ $key ] = (int) $attachment_id;
}

update_option( 'my_ecard_e2e_phase7_media', $media, false );

$gallery_ids = array_map(
	static function ( $key ) use ( $media ) {
		return $media[ $key ];
	},
	$gallery_keys
);

$videos = array(
	array(
		'title' => 'YouTube intro',
		'url'   => 'https://www.youtube.com/watch?v=abc12345678',
	),
	array(
		'title' => 'Vimeo intro',
		'url'   => 'https://vimeo.com/123456789',
	),
);

$cards = array(
	'phase7-no-theme'       => array(
		'title'       => 'No Theme',
		'theme'       => null,
		'designation' => '',
		'email'       => 'notheme@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'map_iframe'  => '<iframe src="https://www.google.com/maps/embed?pb=e2e-native-footer"></iframe>',
		'gallery'     => array( $gallery_ids[0], $gallery_ids[1] ),
		'videos'      => array(
			array(
				'title' => 'Native footer video',
				'url'   => 'https://youtu.be/abc123',
			),
		),
		'settings'    => array(),
	),
	'phase7-missing-theme' => array(
		'title'       => 'Missing Theme',
		'theme'       => 'missing-theme',
		'designation' => '',
		'email'       => 'missing@example.com',
		'location'    => '',
		'gallery'     => false,
		'videos'      => array(),
		'settings'    => array(),
	),
	'phase7-external'       => array(
		'title'       => 'External Theme',
		'theme'       => 'render',
		'designation' => 'Consultant',
		'email'       => 'external@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => false,
		'videos'      => array(),
		'settings'    => array(),
	),
	'phase7-external-media' => array(
		'title'       => 'External Media',
		'theme'       => 'render',
		'designation' => 'Consultant',
		'email'       => 'externalmedia@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => true,
		'videos'      => $videos,
		'settings'    => array(),
	),
	'phase7-gallery'        => array(
		'title'       => 'Gallery Card',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'gallery@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => true,
		'videos'      => array(),
		'settings'    => array(),
	),
	'phase7-videos'         => array(
		'title'       => 'Videos Card',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'videos@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => false,
		'videos'      => $videos,
		'settings'    => array(),
	),
	'phase7-both'           => array(
		'title'       => 'Gallery and Videos',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'both@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => true,
		'videos'      => $videos,
		'settings'    => array(),
	),
	'phase7-none'           => array(
		'title'       => 'No Sections',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'none@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => false,
		'videos'      => array(),
		'settings'    => array(),
	),
	'phase7-actions-off'    => array(
		'title'       => 'Actions Off',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'actionsoff@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => true,
		'videos'      => $videos,
		'settings'    => array(
			'enable_vcard'    => 0,
			'enable_location' => 0,
			'enable_qr'       => 0,
			'enable_share'    => 0,
			'enable_gallery'  => 0,
			'enable_videos'   => 0,
		),
	),
	'phase7-invalid-videos' => array(
		'title'       => 'Invalid Videos',
		'theme'       => 'reference',
		'designation' => '',
		'email'       => 'invalid@example.com',
		'location'    => 'https://maps.google.com/?q=Madrid',
		'gallery'     => false,
		'videos'      => array(
			array(
				'title' => 'Bad scheme',
				'url'   => 'javascript:alert(1)',
			),
			array(
				'title' => 'Relative URL',
				'url'   => '/not-a-video',
			),
		),
		'settings'    => array(),
	),
);

$result = array(
	'base'  => 'http://localhost:8099',
	'media' => array(),
	'posts' => array(),
);

foreach ( $gallery_keys as $key ) {
	$result['media'][ $key ] = wp_get_attachment_url( $media[ $key ] );
}

foreach ( $cards as $slug => $card ) {
	$existing = get_posts(
		array(
			'post_type'        => 'any',
			'post_status'      => 'any',
			'name'             => $slug,
			'numberposts'      => 1,
			'suppress_filters' => true,
		)
	);

	foreach ( $existing as $stale ) {
		wp_delete_post( $stale->ID, true );
	}

	$post_id = wp_insert_post(
		array(
			'post_type'    => 'ecard_digital_card',
			'post_title'   => $card['title'],
			'post_name'    => $slug,
			'post_status'  => 'publish',
			'post_content' => '<p>Phase 7 fixture for ' . $slug . '</p>',
		),
		true
	);

	if ( is_wp_error( $post_id ) ) {
		fwrite( STDERR, 'seed error for ' . $slug . ': ' . $post_id->get_error_message() . "\n" );
		exit( 1 );
	}

	if ( null !== $card['theme'] ) {
		update_post_meta( $post_id, '_my_ecard_theme', $card['theme'] );
	}

	if ( '' !== $card['designation'] ) {
		update_post_meta( $post_id, '_ecard_designation', $card['designation'] );
	}

	if ( '' !== $card['email'] ) {
		update_post_meta( $post_id, '_ecard_email', $card['email'] );
	}

	if ( '' !== $card['location'] ) {
		update_post_meta( $post_id, '_ecard_location', $card['location'] );
	}

	if ( isset( $card['map_iframe'] ) && '' !== $card['map_iframe'] ) {
		update_post_meta( $post_id, '_ecard_map_iframe', $card['map_iframe'] );
	}

	if ( is_array( $card['gallery'] ) ) {
		update_post_meta( $post_id, '_ecard_gallery', $card['gallery'] );
	} elseif ( $card['gallery'] ) {
		update_post_meta( $post_id, '_ecard_gallery', $gallery_ids );
	}

	if ( array() !== $card['videos'] ) {
		update_post_meta( $post_id, '_ecard_videos', $card['videos'] );
	}

	foreach ( $card['settings'] as $key => $value ) {
		update_post_meta( $post_id, '_my_ecard_' . $key, $value );
	}

	$result['posts'][ $slug ] = array(
		'id'  => $post_id,
		'url' => 'http://localhost:8099/ecard/' . $slug . '/',
	);
}

flush_rewrite_rules( true );

echo wp_json_encode( $result, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES ) . "\n";
